const response = $input.first().json;
const content = response.content;
const keyword = $('Loop Over Keywords').item.json;

let text = '';
for (const block of content) {
  if (block.type === 'text') text += block.text;
}

const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
let research;
try {
  research = JSON.parse(cleaned);
} catch(e) {
  research = { error: 'parse failed', raw: text.substring(0, 500) };
}

return [{ json: { ...keyword, research: JSON.stringify(research) } }];

const response = $input.first().json;
const keyword = $('Parse Research').item.json;

let articleContent = '';
for (const block of response.content) {
  if (block.type === 'text') articleContent += block.text;
}

// Quality checks
const wordCount = articleContent.split(/\s+/).length;
const hasFrontmatter = articleContent.includes('---');
const hasPrice = articleContent.includes('/mo') || articleContent.includes('/month');
const hasVerified = articleContent.toLowerCase().includes('verified');
const hasProsCons = articleContent.includes('pros-cons');
const hasTable = articleContent.includes('|---');

const passed = wordCount > 1000 && hasFrontmatter && hasPrice && hasProsCons && hasTable;

if (!passed) {
  console.log(`Quality check failed: words=${wordCount}, frontmatter=${hasFrontmatter}, price=${hasPrice}, prosCons=${hasProsCons}, table=${hasTable}`);
  return [{ json: { passed: false, reason: `Failed checks: words=${wordCount}` } }];
}

// Encode content for GitHub API
const base64Content = Buffer.from(articleContent).toString('base64');

return [{
  json: {
    passed: true,
    slug: keyword.slug,
    title: keyword.title,
    filename: `${keyword.slug}.md`,
    base64Content,
    wordCount
  }
}];

const slug = $('Quality Check').item.json.slug;
const title = $('Quality Check').item.json.title;
const wordCount = $('Quality Check').item.json.wordCount;
console.log(`✅ Published: ${title} (${wordCount} words) → agentbluebook.com/${slug}/`);
return [{ json: { status: 'published', slug, title, wordCount, timestamp: new Date().toISOString() } }];
